// Swarm 1.3.3 row 36 (ST-1 item 5): the capacity table per diagram family and per width comes from REAL renders.
//
// `capacity-table.json` is generated by `capacity-harness.ts` from the product's figure paths (document render and
// preview) and holds, per family, dimension and width: the largest size that passes, the outcome at that size (the
// render proof), and the refusal or defect one step above. This test regenerates the whole file and compares, so a
// number in the guide or the skill can never drift from the engine. After an intended engine change, rewrite it:
//   ROW36_WRITE=1 bun test test/st1-capacity-table/row36-capacity-table.test.ts
// and review the diff of the data file (it is the change of capacity the engine change caused).
//
// Second part: the spec's acceptance case, FIGURE 16.6 of the manual (19 nodes, 4 containers; replay R8), transcribed
// in `gambar-16-6.fixture.json`, rendered at `full`. Its real outcome is recorded in the same data file.
import { useStudioEnv } from "../ported/_env"
useStudioEnv()
import { afterAll, beforeAll, describe, expect, test } from "bun:test"
import { existsSync, readFileSync, writeFileSync } from "node:fs"
import { DIAGRAM_LAYOUTS } from "../../vendor/src/lib/studio/contract/dispatch"
import { FIGURE_BOUNDS } from "../../vendor/src/lib/studio/contract/schema/figure-bounds"
import { FIGURE_WIDTH_MM } from "../../vendor/src/lib/studio/contract/schema/v2/common.schema"
import { DATA_FILE, DIMENSIONS, FIXTURE_FILE, NODE_BOUND, WIDTHS, createHarness, generateDataFile, passes, readJson, serialise, type Cell, type DataFile, type Harness } from "./capacity-harness"

let h: Harness
let fresh: DataFile
let stored: DataFile
let ms = 0

beforeAll(async () => {
  h = await createHarness()
  const t0 = Date.now()
  fresh = await generateDataFile(h)
  ms = Date.now() - t0
  if (process.env.ROW36_WRITE === "1") writeFileSync(DATA_FILE, serialise(fresh))
  stored = existsSync(DATA_FILE) ? (JSON.parse(readFileSync(DATA_FILE, "utf8")) as DataFile) : ({} as DataFile)
}, 240_000)
afterAll(() => h?.dispose())

const cell = (d: DataFile, key: string, width: (typeof WIDTHS)[number]): Cell => {
  const c = d.capacity.rows.find((r) => r.key === key)?.cells.find((x) => x.width === width)
  if (!c) throw new Error(`no cell ${key} @ ${width}`)
  return c
}

describe("row 36 ST-1: the capacity table is the engine's, not a typed number", () => {
  test("the stored data file equals a fresh generation from engine renders (byte for byte)", () => {
    expect(existsSync(DATA_FILE)).toBe(true)
    expect(readFileSync(DATA_FILE, "utf8")).toBe(serialise(fresh))
  })

  test("the harness stays inside its time budget (about two minutes)", () => {
    expect(ms).toBeLessThan(120_000)
  })

  test("every diagram family the engine dispatches has rows, each at both widths", () => {
    const families = new Set(stored.capacity.rows.map((r) => r.family))
    expect([...families].sort()).toEqual(Object.keys(DIAGRAM_LAYOUTS).sort())
    expect(stored.capacity.rows.map((r) => r.key)).toEqual(DIMENSIONS.map((d) => d.key))
    for (const r of stored.capacity.rows) {
      expect(r.cells.map((c) => c.width)).toEqual([...WIDTHS])
      for (const c of r.cells) expect(c.widthMm).toBe(FIGURE_WIDTH_MM[c.width])
    }
  })

  test("no synthetic spec asks for more nodes than the contract allows", () => {
    expect(NODE_BOUND).toBe(FIGURE_BOUNDS.diagramNodes)
    for (const d of DIMENSIONS) expect((d.spec(d.max).nodes as unknown[]).length).toBeLessThanOrEqual(NODE_BOUND)
  })

  test("every number has its render: the outcome at the limit passed on both paths, at the cell's width", () => {
    for (const r of stored.capacity.rows) {
      for (const c of r.cells) {
        if (c.limit === 0) {
          // nothing passes from the start size: the proof is the failure at the start size
          expect(c.atLimit).toBeNull()
          expect(c.aboveSize).toBe(r.start)
          continue
        }
        expect(c.atLimit).not.toBeNull()
        expect(passes(c.atLimit!)).toBe(true)
        expect(c.atLimit!.widthMm).toBe(c.widthMm)
        expect(c.renderLimit).toBeGreaterThanOrEqual(c.limit)
      }
    }
  })

  test("one step above every limit the outcome is recorded: a refusal with code and message, or the defects", () => {
    for (const r of stored.capacity.rows) {
      for (const c of r.cells) {
        if (c.capped) {
          // the scan ended at its own bound (the 24-node contract bound), not at an engine limit
          expect(c.above).toBeNull()
          expect(c.limit).toBe(r.max)
          continue
        }
        expect(c.aboveSize).toBe(c.limit === 0 ? r.start : c.limit + 1)
        const a = c.above!
        expect(passes(a)).toBe(false)
        const failing = a.result !== "pass" ? a : a.preview!
        if (failing.result === "refused") {
          expect(failing.code).toMatch(/^[A-Z_]+$/)
          expect((failing.message ?? "").length).toBeGreaterThan(10)
        } else {
          expect(failing.defects!.length).toBeGreaterThan(0)
          expect(failing.firstDefect).toBeDefined()
        }
      }
    }
  })

  test("spec check: a four-column graph passes at 128 mm (and the fifth column is refused there)", () => {
    const c = cell(fresh, "graph.cols", "text")
    expect(c.widthMm).toBe(128)
    expect(c.limit).toBe(4)
    expect(c.atLimit!.result).toBe("pass")
    expect(c.above!.result).toBe("refused")
    expect(c.above!.code).toBe("FIGURE_OVER_CAPACITY")
    expect(c.above!.message).toContain("muat 4 kolom pada 128 mm")
  })

  test("a direct probe agrees with the table at one cell (the table is not a cached copy)", async () => {
    const d = DIMENSIONS.find((x) => x.key === "layered.perTier")!
    const c = cell(stored, "layered.perTier", "full")
    expect(passes(await h.probe(d.spec(c.limit), "full"))).toBe(true)
    expect(passes(await h.probe(d.spec(c.limit + 1), "full"))).toBe(false)
  })
})

describe("row 36 ST-1: FIGURE 16.6 of the manual (R8) at `full`", () => {
  test("the transcription holds what the spec names: 19 nodes and 4 containers; every edge joins transcribed nodes", () => {
    const fx = readJson(FIXTURE_FILE)
    expect(fx.nodes.length).toBe(19)
    expect(fx.containers.length).toBe(4)
    const ids = new Set(fx.nodes.map((n: { id: string }) => n.id))
    expect(ids.size).toBe(19)
    for (const e of fx.edges) expect(ids.has(e.from) && ids.has(e.to)).toBe(true)
    for (const n of fx.nodes) expect(fx.containers.some((c: { id: string }) => c.id === n.container)).toBe(true)
    expect(stored.gambar16_6.fixture).toEqual({ nodes: 19, containers: 4, edges: fx.edges.length })
  })

  test("the recorded outcome is the engine's outcome today (regenerated and compared)", () => {
    expect(stored.gambar16_6).toEqual(fresh.gambar16_6)
    for (const c of stored.gambar16_6.cases) {
      if (c.split && "absent" in c.split) expect(c.outcomes.length).toBe(0)
      else expect(c.outcomes.length).toBe(c.sheets)
    }
  })

  test("every sheet of every case has a recorded outcome with its reason when it does not pass", () => {
    for (const c of stored.gambar16_6.cases) {
      for (const o of c.outcomes) {
        if (passes(o)) continue
        const failing = o.result !== "pass" ? o : o.preview!
        expect(failing.result === "refused" ? (failing.message ?? "").length : failing.defects!.length).toBeGreaterThan(0)
      }
    }
  })

  // The acceptance of ST-1 says the figure passes at `full` in at most two sheets. This test states the real result
  // and fails when it changes, in either direction, so the report and the guide are corrected with the engine.
  test("acceptance status as measured: `passesInAtMostTwoSheets` and `passesUnchanged` equal the stored values", () => {
    expect(fresh.gambar16_6.passesInAtMostTwoSheets).toBe(stored.gambar16_6.passesInAtMostTwoSheets)
    expect(fresh.gambar16_6.passesUnchanged).toBe(stored.gambar16_6.passesUnchanged)
    // as transcribed, the manual's figure is refused before layout (an unlabelled connector)
    expect(fresh.gambar16_6.cases[0].outcomes[0].result).toBe("refused")
  })
})
